import heapq


def solve(data):
    nodes = list(data['nodes'])
    node_set = set(nodes)
    adj = {n: set() for n in nodes}
    indeg = {n: 0 for n in nodes}
    seen = set()
    for pair in data['edges']:
        before, after = pair[0], pair[1]
        if before not in node_set or after not in node_set:
            raise ValueError('edge endpoint not in nodes: %r' % ((before, after),))
        if before == after:
            raise ValueError('self edge not allowed: %r' % (before,))
        key = (before, after)
        if key in seen:
            continue
        seen.add(key)
        adj[before].add(after)
        indeg[after] += 1
    heap = [n for n in nodes if indeg[n] == 0]
    heapq.heapify(heap)
    result = []
    while heap:
        n = heapq.heappop(heap)
        result.append(n)
        for m in adj[n]:
            indeg[m] -= 1
            if indeg[m] == 0:
                heapq.heappush(heap, m)
    if len(result) != len(nodes):
        raise ValueError('graph contains a cycle')
    return result

