def solve(data):
    k = data['k']
    if k < 0:
        raise ValueError('k must be non-negative')
    best = {}
    for e in data['entries']:
        if not e['active']:
            continue
        name = e['name']
        score = e['score']
        if name not in best or score > best[name]:
            best[name] = score
    ranked = sorted(best.items(), key=lambda kv: (-kv[1], kv[0]))
    return [name for name, _ in ranked[:k]]

